head.r/main.tf:
terraform {
  backend "s3" {}
}
data "aws_iam_policy_document" "d" {
  dynamic "statement" {
    for_each = sensitive(["*"])
    content {
      actions   = ["s3:GetObject"]
      resources = [statement.value]
    }
  }
}
resource "aws_iam_policy" "p" {
  name   = "p"
  policy = data.aws_iam_policy_document.d.json
}

base.r/main.tf:
terraform {
  backend "s3" {}
}
variable "cfg" {
  type = object({
    actions = optional(list(string), ["s3:GetObject"])
    nested  = optional(object({ flag = optional(bool, true) }), {})
  })
  default = {}
}
resource "aws_iam_policy" "p" {
  name   = "p"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = var.cfg.actions, Resource = "*" }] })
}
resource "aws_sqs_queue" "q" {
  name = "q"
  tags = { flag = tostring(var.cfg.nested.flag) }
}

head.r/main.tf:
terraform {
  backend "s3" {}
}
variable "cfg" {
  type = object({
    actions = optional(list(string), ["*"])
    nested  = optional(object({ flag = optional(bool, true) }), {})
  })
  default = {}
}
resource "aws_iam_policy" "p" {
  name   = "p"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = var.cfg.actions, Resource = "*" }] })
}
resource "aws_sqs_queue" "q" {
  name = "q"
  tags = { flag = tostring(var.cfg.nested.flag) }
}

terraform {
  backend "s3" {}
}
variable "arn" {}
resource "aws_s3_bucket_policy" "p" {
  bucket = "b"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Principal = "*", Action = "s3:GetObject", Resource = "arn:aws:s3:::b/*", Condition = { StringLike = { "aws:SourceArn" = var.arn } } }] })
}

terraform {
  backend "s3" {}
}
variable "items" {}
data "aws_iam_policy_document" "d" {
  dynamic "statement" {
    for_each = var.items
    content {
      effect    = "Deny"
      actions   = ["s3:GetObject"]
      resources = ["*"]
    }
  }
}
resource "aws_iam_policy" "p" {
  name   = "p"
  policy = data.aws_iam_policy_document.d.json
}
